import{_ as s,C as i,o as a,c as l,a2 as h,b as d,w as o,a as t,E as c,a3 as g,j as n}from"./chunks/framework.CCXDMzJr.js";const v=JSON.parse('{"title":"What is GPU FinOps & Token Chargeback?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/what-is-finops.md","filePath":"guide/what-is-finops.md"}'),p={name:"guide/what-is-finops.md"};function m(u,e,b,f,k,y){const r=i("Mermaid");return a(),l("div",null,[e[1]||(e[1]=h('<h1 id="what-is-gpu-finops-token-chargeback" tabindex="-1">What is GPU FinOps &amp; Token Chargeback? <a class="header-anchor" href="#what-is-gpu-finops-token-chargeback" aria-label="Permalink to &quot;What is GPU FinOps &amp; Token Chargeback?&quot;">​</a></h1><p>Welcome! If you are new to AI infrastructure, FinOps, or Kubernetes cost tracking, this guide explains everything from first principles.</p><hr><h2 id="_1-the-core-problem-why-is-ai-compute-so-expensive" tabindex="-1">1. The Core Problem: Why is AI Compute So Expensive? <a class="header-anchor" href="#_1-the-core-problem-why-is-ai-compute-so-expensive" aria-label="Permalink to &quot;1. The Core Problem: Why is AI Compute So Expensive?&quot;">​</a></h2><p>When an enterprise or startup builds AI applications (like chatbots, code generators, or image models), they rely on <strong>NVIDIA GPUs</strong> (graphics processing units) and <strong>LLM inference APIs</strong> (like vLLM, Ollama, OpenAI).</p><p>Unlike traditional web servers (which cost a few cents a day), <strong>GPUs cost up to $4.00 per hour PER GPU</strong>. An 8-GPU node running an AI model costs <strong>$2,300+ per month</strong>.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Traditional CPU Web Server</th><th style="text-align:left;">NVIDIA H100 / A100 GPU Node</th></tr></thead><tbody><tr><td style="text-align:left;">~$30.00 / month</td><td style="text-align:left;">~$2,500.00 to $20,000.00 / month</td></tr></tbody></table><p>When multiple software teams share the same Kubernetes cluster, the monthly cloud bill arrives as <strong>one huge sum</strong> (e.g. <code>$50,000 / month</code>).</p><p><strong>The Problem</strong>: Platform engineering cannot tell:</p><ul><li>Who spent the money?</li><li>Which department (NLP team, Computer Vision team, Finance AI team) used how many GPU-hours?</li><li>Which team processed how many LLM tokens?</li></ul><hr><h2 id="_2-what-is-finops" tabindex="-1">2. What is FinOps? <a class="header-anchor" href="#_2-what-is-finops" aria-label="Permalink to &quot;2. What is FinOps?&quot;">​</a></h2><p><strong>FinOps</strong> stands for <strong>Financial Operations</strong> (or Cloud Financial Management).</p><p>It is the discipline of bringing financial accountability to the variable spend model of cloud and AI infrastructure. Instead of finding out your cloud bill at the end of the month, FinOps provides:</p><ol><li><strong>Visibility</strong>: Real-time tracking of who is spending what.</li><li><strong>Attribution</strong>: Mapping costs directly to teams, products, or departments.</li><li><strong>Optimization</strong>: Identifying idle GPUs and oversized workloads.</li></ol><hr><h2 id="_3-what-is-chargeback-vs-showback" tabindex="-1">3. What is Chargeback vs. Showback? <a class="header-anchor" href="#_3-what-is-chargeback-vs-showback" aria-label="Permalink to &quot;3. What is Chargeback vs. Showback?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>What It Means</th><th>Real-World Analogy</th></tr></thead><tbody><tr><td><strong>Showback</strong></td><td>Generating a report that <strong>shows</strong> each team how much money their AI models spent, without actually billing their department budget.</td><td>Sending a mock utility bill to each roommate to make them aware of their electricity usage.</td></tr><tr><td><strong>Chargeback</strong></td><td>Actually <strong>deducting or billing</strong> the cost from the specific team&#39;s internal department budget.</td><td>Splitting and charging the utility bill based on who ran the air conditioner.</td></tr></tbody></table><p>Slicemeter generates the clean data, CSVs, tables, and PDF reports required to do both <strong>Showback</strong> and <strong>Chargeback</strong>.</p><hr><h2 id="_4-what-is-token-chargeback" tabindex="-1">4. What is Token Chargeback? <a class="header-anchor" href="#_4-what-is-token-chargeback" aria-label="Permalink to &quot;4. What is Token Chargeback?&quot;">​</a></h2><p>Large Language Models (LLMs) do not process text in words: they process text in <strong>Tokens</strong> (roughly 4 characters of text).</p><p>When multiple teams send requests to a shared internal AI endpoint (e.g., <code>http://ollama-service.internal</code> or <code>http://vllm-service.internal</code>):</p><ul><li>Team A might generate <strong>1,000,000 prompt tokens</strong> (e.g., summarizing large PDF documents).</li><li>Team B might generate <strong>50,000 prompt tokens</strong> (e.g., quick search queries).</li></ul><p>Without Slicemeter, both teams appear to be hitting the same URL. Slicemeter acts as a lightweight observer or proxy to record exactly how many tokens were generated by each namespace and team.</p><hr><h2 id="_5-ai-model-training-vs-llm-inference-finops" tabindex="-1">5. AI Model Training vs. LLM Inference FinOps <a class="header-anchor" href="#_5-ai-model-training-vs-llm-inference-finops" aria-label="Permalink to &quot;5. AI Model Training vs. LLM Inference FinOps&quot;">​</a></h2><p>Slicemeter provides financial management across <strong>both major categories of AI workloads</strong>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Workload Type</th><th style="text-align:left;">What Slicemeter Tracks</th><th style="text-align:left;">Primary Business Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Model Training &amp; Fine-Tuning</strong> (PyTorch, DeepSpeed, Ray, Kubeflow)</td><td style="text-align:left;">Hardware GPU-seconds, VRAM consumption, spot/on-demand pricing, and zero-utilization idle waste.</td><td style="text-align:left;"><strong>High-ROI Waste Prevention</strong>: Prevents deadlocked or crashed PyTorch jobs from idling 32x A100 GPUs at $32/hr over weekends.</td></tr><tr><td style="text-align:left;"><strong>LLM Inference &amp; Serving</strong> (vLLM, Ollama, OpenAI API, HuggingFace TGI)</td><td style="text-align:left;">Hardware GPU time-slicing + HTTP prompt/completion token consumption (<code>/v1/chat/completions</code>).</td><td style="text-align:left;"><strong>Token Chargeback</strong>: Accurately bills internal departments based on actual prompt/completion token volumes processed.</td></tr></tbody></table><hr><h2 id="_6-how-slicemeter-solves-this-non-obtrusively" tabindex="-1">6. How Slicemeter Solves This (Non-Obtrusively) <a class="header-anchor" href="#_6-how-slicemeter-solves-this-non-obtrusively" aria-label="Permalink to &quot;6. How Slicemeter Solves This (Non-Obtrusively)&quot;">​</a></h2><p>Slicemeter installs into your Kubernetes cluster in <strong>less than 2 minutes</strong>.</p>',32)),(a(),d(g,null,{default:o(()=>[c(r,{id:"mermaid-212",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%221.%20Metric%20Scraping%22%5D%20--%3E%20B%5B%222.%20Attribution%20Engine%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%223.%20Automated%20Ledger%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%224.%20Chargeback%20Reports%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=n("p",null,[t("Ready to get started? Head over to the "),n("a",{href:"/guide/quickstart.html"},"5-Minute Quickstart Guide"),t("!")],-1))])}const P=s(p,[["render",m]]);export{v as __pageData,P as default};
